#!/usr/bin/env node
/**
 * scripts/generate-api-docs.mjs
 *
 * Level 5.7 — auto-generated API reference.
 *
 * Walks src/app/api/**\/route.ts, extracts:
 *   - exported HTTP method handlers (GET, POST, PUT, DELETE)
 *   - zod schemas (best-effort: regex over `z.object` declarations)
 *   - JSDoc comment above each route file
 *
 * Writes docs/API.md. Re-run after any API change. Idempotent.
 *
 * No deps — uses node fs + path. Trade-off vs zod-to-openapi: shallower
 * introspection (no nested schema types, no request body examples),
 * zero install footprint.
 */
import { readFileSync, writeFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, relative, basename } from "node:path";

const ROOT = process.cwd();
const API_DIR = join(ROOT, "src/app/api");
const OUT_PATH = join(ROOT, "docs/API.md");

const METHODS = ["GET", "POST", "PUT", "DELETE", "PATCH"];

function walk(dir) {
  const out = [];
  if (!existsSync(dir)) return out;
  for (const entry of readdirSync(dir)) {
    const fp = join(dir, entry);
    const s = statSync(fp);
    if (s.isDirectory()) out.push(...walk(fp));
    else if (entry === "route.ts" || entry === "route.tsx") out.push(fp);
  }
  return out;
}

function routePath(file) {
  const rel = relative(API_DIR, file).replaceAll("\\", "/");
  // /app/api/{segments}/route.ts -> /api/{segments}
  const segs = rel.split("/").slice(0, -1); // drop route.ts
  const dynamic = segs.map((s) => (s.startsWith("[") && s.endsWith("]") ? `:${s.slice(1, -1)}` : s));
  return "/api/" + dynamic.join("/");
}

function extractSchemas(content) {
  const schemas = [];
  const re = /(?:const|export const)\s+(\w+Schema|\w+)\s*=\s*z\.object\s*\(([\s\S]*?)\)\s*\.?\s*(\.\w+\([^)]*\))*;?/g;
  let m;
  while ((m = re.exec(content)) !== null) {
    const fields = [...m[2].matchAll(/(\w+):\s*z\.(\w+)\(/g)].map((x) => x[1]);
    if (fields.length > 0) {
      schemas.push({ name: m[1], fields });
    }
  }
  return schemas;
}

function extractJsDoc(content) {
  // grab /** ... */ block at top of file (first occurrence)
  const m = content.match(/^\s*\/\*\*([\s\S]*?)\*\//);
  if (!m) return null;
  // strip leading * per line
  return m[1].split("\n").map((l) => l.replace(/^\s*\*\s?/, "").trim()).filter(Boolean).join("\n");
}

function extractMethods(content) {
  return METHODS.filter((m) => new RegExp(`export\\s+(async\\s+)?function\\s+${m}\\b`).test(content));
}

function renderRoute(file) {
  const content = readFileSync(file, "utf8");
  const path = routePath(file);
  const methods = extractMethods(content);
  const schemas = extractSchemas(content);
  const doc = extractJsDoc(content);

  let md = `### ${methods.join(", ")} \`${path}\`\n\n`;
  if (doc) md += `${doc}\n\n`;
  if (schemas.length > 0) {
    md += `**Request schemas:**\n`;
    for (const s of schemas) {
      md += `- \`${s.name}\`: ${s.fields.join(", ")}\n`;
    }
    md += "\n";
  } else if (methods.includes("POST") || methods.includes("PUT")) {
    md += `**Request:** JSON or FormData (see source).\n\n`;
  }
  md += `Source: \`${relative(ROOT, file)}\`\n\n`;
  return md;
}

function main() {
  const files = walk(API_DIR);
  const groups = {};
  for (const f of files) {
    const seg = f.split("/api/")[1].split("/")[0];
    (groups[seg] ||= []).push(f);
  }

  let md = "# API Reference\n\n";
  md += `> Auto-generated by \`scripts/generate-api-docs.mjs\`.\n`;
  md += `> Re-run after any route file change. Last generated: ${new Date().toISOString()}.\n\n`;
  md += `${files.length} routes across ${Object.keys(groups).length} resource groups.\n\n`;
  md += "## Table of Contents\n\n";
  for (const g of Object.keys(groups).sort()) {
    md += `- **${g}**\n`;
    for (const f of groups[g]) {
      md += `  - \`${routePath(f)}\`\n`;
    }
  }
  md += "\n## Routes\n\n";
  for (const g of Object.keys(groups).sort()) {
    md += `## \`${g}\`\n\n`;
    for (const f of groups[g].sort()) {
      md += renderRoute(f);
    }
  }

  writeFileSync(OUT_PATH, md);
  console.log(`wrote ${OUT_PATH} (${files.length} routes, ${md.length} bytes)`);
}

main();